import type { EVENT } from "~/enum/event.ts";
import { okAsync, type ResultAsync } from "npm:neverthrow@^8.2.0";

export class EventEmitter extends EventTarget {
    public events: {type: EVENT, listener: EventListenerOrEventListenerObject | null}[] = [];

    constructor() {
        super();
    }

    public emit = (type: EVENT, detail?: any) : ResultAsync<void, Error> => {      
        this.dispatchEvent(new CustomEvent(type, {detail}));

        return okAsync(undefined);
    }

    public on = (type: EVENT, listener?: any) : ResultAsync<void, Error> => {
        this.addEventListener(type, listener || null);
        this.events.push({type, listener: listener || null});

        return okAsync(undefined);
    }
    
    public once = (type: EVENT, listener?: any) : ResultAsync<void, Error> => {
        const listenerExists = this.events.find((event) => event.type === type);

        if(!listenerExists) {
            this.on(type, listener);
        }

        return okAsync(undefined);
    }
}